const app = document.querySelector("#app");
const toastBox = document.querySelector("#toast");
const state = { route: location.hash.slice(1) || "home", accounts: [], categories: [], selected: new Set(), files: [], staged: null,
  transactionFilters: { search:"", dateRange:"all", from:"", to:"", accountId:"", categoryId:"", categorySearch:"", status:"" } };

const esc = (value = "") => String(value).replace(/[&<>"']/g, (c) => ({ "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#039;" })[c]);
const cash = (minor, currency = "USD") => new Intl.NumberFormat("en-US", { style:"currency", currency }).format(Number(minor || 0) / 100);
const date = (value) => value ? new Date(value + "T00:00:00").toLocaleDateString("en-US", { month:"short", day:"numeric", year:"numeric" }) : "—";
const request = async (path, options = {}) => {
  const response = await fetch(path, { headers:{ "content-type":"application/json" }, ...options });
  const body = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(body.error || "Request failed");
  return body;
};
function toast(message) { toastBox.textContent = message; toastBox.className = "toast-visible"; clearTimeout(toast.timer); toast.timer = setTimeout(() => toastBox.className = "", 5000); }
function closeOverlay() { document.querySelectorAll(".modal-backdrop,.drawer").forEach((node) => node.remove()); }
function nav(meta = "") {
  const links = [["home","Home"],["transactions","Transactions"],["budget","Budget"],["plan","Plan"],["accounts","Accounts"],["rules","Rules"]];
  return '<nav class="nav"><span class="wordmark">Household</span>' + links.map(([id,label]) => '<a href="#' + id + '" class="' + ((state.route === id || (id === "budget" && ["category","recurring","irregular","budget-settings","categories"].some((prefix) => state.route.startsWith(prefix)))) ? "active" : "") + '">' + label + '</a>').join("") + '<span class="nav-meta">' + esc(meta) + '</span></nav>';
}
const shell = (content, meta = "") => '<div class="shell"><div class="frame">' + nav(meta) + content + '</div></div>';
const accountOptions = (selected = "") => '<option value="">Choose account…</option>' + state.accounts.map((a) => '<option value="' + a.id + '" ' + (selected === a.id ? "selected" : "") + '>' + esc(a.name) + (a.lastFour ? " ···" + esc(a.lastFour) : "") + '</option>').join("");
const categoryOptions = (selected = "") => '<option value="">Uncategorized</option>' + state.categories.filter((c) => c.active).map((c) => '<option value="' + c.id + '" ' + (selected === c.id ? "selected" : "") + '>' + esc(c.name) + '</option>').join("");
const accountRoles = ["Operating cash","Income","Emergency reserve","Sinking funds · cash","Spending · paid in full","Growth capital","Unassigned"];
const accountTypes = [["checking","Checking"],["savings","Savings"],["credit-card","Credit card"],["investment","Investment"]];
const selectOptions = (items, selected = "") => items.map(([value,label]) => '<option value="' + esc(value) + '" ' + (selected === value ? "selected" : "") + '>' + esc(label) + '</option>').join("");
const roleOptions = (selected = "") => accountRoles.map((role) => '<option ' + (selected === role ? "selected" : "") + '>' + esc(role) + '</option>').join("");
const accountEditButton = (field, value, label, kind = "text") => '<button type="button" class="account-field" data-field="' + field + '" data-value="' + esc(value ?? "") + '" data-kind="' + kind + '" title="Click to edit">' + esc(label || "—") + '</button>';
function groupedCategoryChoices(selected = "", search = "") {
  const groups = {}, term = search.trim().toLowerCase();
  state.categories.filter((c) => c.active && (!term || c.name.toLowerCase().includes(term) || c.planningGroupName.toLowerCase().includes(term))).forEach((c) => (groups[c.planningGroupName] ||= []).push(c));
  return '<button type="button" class="category-choice ' + (!selected ? "selected" : "") + '" data-id=""><span class="choice-mark"></span>All categories</button>' + Object.entries(groups).map(([name,categories]) => '<div class="category-choice-group"><div class="category-group-label">' + esc(name) + '</div>' + categories.map((c) => '<button type="button" class="category-choice ' + (selected === c.id ? "selected" : "") + '" data-id="' + c.id + '"><span class="choice-mark"></span>' + esc(c.name) + '</button>').join("") + '</div>').join("");
}
const selectedCategoryLabel = (id) => state.categories.find((category) => category.id === id)?.name || "All categories";

async function shared() { [state.accounts, state.categories] = await Promise.all([request("/api/accounts"), request("/api/categories")]); }
async function render() {
  state.route = location.hash.slice(1) || "home"; closeOverlay();
  try {
    await shared();
    const routes = { home, transactions, budget, accounts, categories, recurring, irregular, "budget-settings":budgetSettings, rules, history, plan,
      "plan-household":planHousehold, "plan-income":planIncome, "plan-cash":planCash, "plan-sinking":planSinking,
      "plan-capital":planCapital, "plan-accounts":planAccounts, "plan-assumptions":planAssumptions };
    if (state.route.startsWith("category/")) await categoryDetail(state.route.split("/")[1]);
    else await (routes[state.route] || home)();
  } catch (error) { app.innerHTML = shell('<div class="empty"><h2>Bloom could not open.</h2><p>' + esc(error.message) + '</p><button class="button" onclick="location.reload()">Try again</button></div>'); }
}
function common() {
  document.querySelectorAll('[data-action="import"]').forEach((b) => b.addEventListener("click", openImport));
  document.querySelectorAll('[data-action="history"]').forEach((b) => b.addEventListener("click", () => location.hash = "history"));
}

async function home() {
  const o = await request("/api/overview");
  app.innerHTML = shell('<main class="landing"><section class="landing-copy"><p class="eyebrow">PHASE 3 · LIVING PLAN</p><h1>Your household ledger,<br><em>ready for decisions.</em></h1><p>Turn normalized activity, budgets, balances, and explicit assumptions into traceable household requirements.</p><div class="toolbar" style="margin-top:28px"><a class="button primary" href="#plan">Open the plan</a><a class="button" href="#transactions">Review transactions</a></div></section><section class="landing-side"><article><h3>' + Number(o.transactionCount).toLocaleString() + ' transactions</h3><p>' + Number(o.reviewCount || 0) + ' need categorization.</p></article><article><h3>' + o.accountCount + ' accounts</h3><p>Balances and planning roles stay explicit.</p></article><article><h3>' + o.ruleCount + ' rules</h3><p>Cleanup and categorization run on imports.</p></article><article><h3>Source evidence retained</h3><p>Every planning result names its formula and inputs.</p></article></section></main>', "API 0.6.1 · " + o.transactionCount + " records");
  common();
}

function transactionContent(result, searching = false) {
  const rows = result.rows.map((t) => '<tr><td><input type="checkbox" class="tx-check" value="' + t.id + '" ' + (state.selected.has(t.id) ? "checked" : "") + ' style="width:auto"></td><td class="mono">' + date(t.postedDate) + '</td><td><div class="merchant">' + esc(t.merchantName || t.originalDescription) + '</div><div class="raw">' + esc(t.originalDescription) + '</div></td><td>' + (t.isTransfer ? '<span class="muted">Transfer · excluded</span>' : t.splitCount ? '<span class="badge">' + t.splitCount + ' parts</span>' : t.categoryName ? esc(t.categoryName) : '<span class="badge warn">Uncategorized</span>') + '</td><td class="amount">' + cash(t.amountMinor,t.currency) + '</td><td class="mono">' + esc(t.accountName) + '</td><td class="mono">' + (t.flagged ? "flagged " : "") + (t.notes ? "note " : "") + (t.transferPairId ? "paired ✓" : "") + '</td><td><button class="button link tx-open" data-id="' + t.id + '">›</button></td></tr>').join("");
  if (result.rows.length) return '<div class="table-wrap"><table><thead><tr><th></th><th>Date ↓</th><th>Merchant</th><th>Category</th><th class="amount">Amount</th><th>Account</th><th>Flags</th><th></th></tr></thead><tbody>' + rows + '</tbody></table></div><div class="panel-head mono"><span>' + result.summary.count + ' records</span><span>net ' + cash(result.summary.amountMinor) + ' · transfers excluded</span></div>';
  return searching ? '<div class="empty"><h2>No matching transactions.</h2><p>Try a different merchant, memo, amount, or note.</p></div>' : '<div class="empty"><h2>No transactions yet.</h2><p>Add an account, then import one or more CSVs. Re-importing overlapping data is safe.</p><button class="button primary" data-action="import">Import CSV</button></div>';
}
function bindTransactionRows() {
  document.querySelectorAll(".tx-check").forEach((box) => box.addEventListener("change", () => { box.checked ? state.selected.add(box.value) : state.selected.delete(box.value); render(); }));
  document.querySelectorAll(".tx-open").forEach((b) => b.addEventListener("click", () => openTransaction(b.dataset.id)));
}
function isoDate(value) {
  const year = value.getFullYear(), month = String(value.getMonth() + 1).padStart(2,"0"), day = String(value.getDate()).padStart(2,"0");
  return `${year}-${month}-${day}`;
}
function transactionDateBounds(range) {
  const today = new Date(), year = today.getFullYear(), month = today.getMonth();
  if (range === "this-month") return { from:isoDate(new Date(year,month,1)), to:isoDate(today) };
  if (range === "last-month") return { from:isoDate(new Date(year,month-1,1)), to:isoDate(new Date(year,month,0)) };
  if (range === "ytd") return { from:`${year}-01-01`, to:isoDate(today) };
  return { from:"", to:"" };
}
function transactionFilterQuery() {
  const filters = state.transactionFilters, params = new URLSearchParams({ limit:"250" });
  if (filters.search.trim()) params.set("search",filters.search.trim());
  const dates = filters.dateRange === "custom" ? { from:filters.from, to:filters.to } : transactionDateBounds(filters.dateRange);
  if (dates.from) params.set("from",dates.from); if (dates.to) params.set("to",dates.to);
  if (filters.accountId) params.set("accountId",filters.accountId);
  if (filters.categoryId) params.set("categoryId",filters.categoryId);
  if (filters.status === "flagged") params.set("flagged","true");
  if (filters.status === "transfers") params.set("transfers","true");
  if (filters.status === "uncategorized") params.set("categoryId","uncategorized");
  return params;
}
async function transactions() {
  const filters = state.transactionFilters, result = await request("/api/transactions?" + transactionFilterQuery());
  const bulk = state.selected.size ? '<div class="bulk"><strong>' + state.selected.size + ' selected</strong><select id="bulk-category" style="max-width:220px">' + categoryOptions() + '</select><button class="button primary" id="bulk-save">Set category</button><button class="button" id="bulk-transfer">Mark transfer</button><button class="button" id="bulk-flag">Flag</button></div>' : "";
  const accountFilters = '<option value="">All accounts</option>' + state.accounts.map((a) => '<option value="' + a.id + '" ' + (filters.accountId === a.id ? "selected" : "") + '>' + esc(a.name) + (a.lastFour ? " ···" + esc(a.lastFour) : "") + '</option>').join("");
  const categoryChoices = groupedCategoryChoices(filters.categoryId, filters.categorySearch || "");
  const customDates = '<div class="custom-dates ' + (filters.dateRange === "custom" ? "visible" : "") + '" id="custom-dates"><label><span>FROM</span><input id="filter-from" type="date" value="' + esc(filters.from) + '"></label><label><span>TO</span><input id="filter-to" type="date" value="' + esc(filters.to) + '"></label></div>';
  app.innerHTML = shell('<main class="page"><div class="toolbar"><div class="search"><input id="search" type="search" autocomplete="off" aria-label="Search transactions" placeholder="merchant, memo, amount, notes" value="' + esc(filters.search) + '"></div><button class="button" data-action="history">Import history</button><button class="button primary" data-action="import">Import CSV</button></div><div class="transaction-filters" aria-label="Transaction filters"><label><span>DATE</span><select id="filter-date"><option value="all">All time</option><option value="this-month" ' + (filters.dateRange === "this-month" ? "selected" : "") + '>This month</option><option value="last-month" ' + (filters.dateRange === "last-month" ? "selected" : "") + '>Last month</option><option value="ytd" ' + (filters.dateRange === "ytd" ? "selected" : "") + '>Year to date</option><option value="custom" ' + (filters.dateRange === "custom" ? "selected" : "") + '>Custom</option></select></label>' + customDates + '<label><span>ACCOUNT</span><select id="filter-account">' + accountFilters + '</select></label><div class="category-filter"><span>CATEGORY</span><div class="category-picker"><button type="button" class="category-trigger" id="filter-category" aria-haspopup="listbox" aria-expanded="false">' + esc(selectedCategoryLabel(filters.categoryId)) + '<span>⌄</span></button><div class="category-menu" id="category-menu" hidden><div class="category-menu-search"><span>⌕</span><input id="filter-category-search" type="search" autocomplete="off" placeholder="Search categories…" aria-label="Filter categories" value="' + esc(filters.categorySearch || "") + '"></div><div class="category-options" id="category-options" role="listbox">' + categoryChoices + '</div></div></div></div><label><span>STATUS</span><select id="filter-status"><option value="">Any status</option><option value="uncategorized" ' + (filters.status === "uncategorized" ? "selected" : "") + '>Needs review</option><option value="flagged" ' + (filters.status === "flagged" ? "selected" : "") + '>Flagged</option><option value="transfers" ' + (filters.status === "transfers" ? "selected" : "") + '>Transfers</option></select></label><button class="button link clear-filters" id="clear-filters">Clear filters</button></div>' + bulk + '<section id="transaction-results" class="panel ' + (bulk ? "table-panel with-bulk" : "") + '" aria-live="polite">' + transactionContent(result, transactionFilterQuery().toString() !== "limit=250") + '</section></main>', result.summary.count + " records · " + Number(result.summary.uncategorizedCount || 0) + " need review");
  common();
  const search = document.querySelector("#search"); let searchTimer, searchRequest = 0;
  const refreshResults = async () => { const requestId = ++searchRequest; try { const query = transactionFilterQuery(), q = await request("/api/transactions?" + query); if (requestId !== searchRequest) return; document.querySelector("#transaction-results").innerHTML = transactionContent(q, query.toString() !== "limit=250"); document.querySelector(".nav-meta").textContent = q.summary.count + " matches"; bindTransactionRows(); document.querySelector('#transaction-results [data-action="import"]')?.addEventListener("click", openImport); } catch (error) { if (requestId === searchRequest) toast(error.message); } };
  search?.addEventListener("input", () => { state.transactionFilters.search = search.value; clearTimeout(searchTimer); searchTimer = setTimeout(refreshResults,200); });
  document.querySelector("#filter-date").addEventListener("change", (event) => { filters.dateRange = event.target.value; document.querySelector("#custom-dates").classList.toggle("visible",filters.dateRange === "custom"); if (filters.dateRange !== "custom") refreshResults(); });
  document.querySelector("#filter-account").addEventListener("change", (event) => { filters.accountId = event.target.value; refreshResults(); });
  const picker=document.querySelector(".category-picker"), menu=document.querySelector("#category-menu"), trigger=document.querySelector("#filter-category"), categorySearch=document.querySelector("#filter-category-search"), options=document.querySelector("#category-options");
  const closeCategoryMenu=()=>{menu.hidden=true;trigger.setAttribute("aria-expanded","false");document.removeEventListener("click",outsideCategoryMenu)};
  const outsideCategoryMenu=(event)=>{if(!picker.contains(event.target))closeCategoryMenu()};
  const bindCategoryChoices=()=>options.querySelectorAll(".category-choice").forEach((choice)=>choice.onclick=()=>{filters.categoryId=choice.dataset.id;trigger.firstChild.textContent=selectedCategoryLabel(filters.categoryId);closeCategoryMenu();refreshResults()});
  trigger.onclick=(event)=>{event.stopPropagation();const opening=menu.hidden;menu.hidden=!opening;trigger.setAttribute("aria-expanded",String(opening));if(opening){categorySearch.focus();setTimeout(()=>document.addEventListener("click",outsideCategoryMenu),0)}else closeCategoryMenu()};
  menu.onclick=(event)=>event.stopPropagation();
  categorySearch.addEventListener("input",()=>{filters.categorySearch=categorySearch.value;options.innerHTML=groupedCategoryChoices(filters.categoryId,filters.categorySearch);bindCategoryChoices()});
  bindCategoryChoices();
  document.querySelector("#filter-status").addEventListener("change", (event) => { filters.status = event.target.value; refreshResults(); });
  document.querySelector("#filter-from").addEventListener("change", (event) => { filters.from = event.target.value; refreshResults(); });
  document.querySelector("#filter-to").addEventListener("change", (event) => { filters.to = event.target.value; refreshResults(); });
  document.querySelector("#clear-filters").addEventListener("click", () => { state.transactionFilters = { search:"", dateRange:"all", from:"", to:"", accountId:"", categoryId:"", categorySearch:"", status:"" }; transactions(); });
  bindTransactionRows();
  document.querySelector("#bulk-save")?.addEventListener("click", () => bulkUpdate({ categoryId:document.querySelector("#bulk-category").value }));
  document.querySelector("#bulk-transfer")?.addEventListener("click", () => bulkUpdate({ isTransfer:true }));
  document.querySelector("#bulk-flag")?.addEventListener("click", () => bulkUpdate({ flagged:true }));
}
async function bulkUpdate(changes) { await request("/api/transactions",{method:"PATCH",body:JSON.stringify({ids:[...state.selected],changes})}); state.selected.clear(); toast("Transactions updated"); render(); }

async function openTransaction(id) {
  const t = await request("/api/transactions/" + id); const node = document.createElement("aside"); node.className = "drawer";
  node.innerHTML = '<div class="modal-head"><span class="mono">txn ' + t.id.slice(0,8) + '</span><h2>Transaction detail</h2><button data-close>×</button></div><div class="modal-body"><div class="detail-hero"><div><h1>' + esc(t.merchantName || t.originalDescription) + '</h1><span class="mono">' + date(t.postedDate) + ' · ' + esc(t.accountName) + '</span></div><div class="amount">' + cash(t.amountMinor,t.currency) + '</div></div><form id="tx-form" class="form-grid"><div class="field full"><label>MERCHANT</label><input name="merchantName" value="' + esc(t.merchantName || t.originalDescription) + '"></div><div class="field full"><label>CATEGORY</label><select name="categoryId">' + categoryOptions(t.categoryId) + '</select></div><div class="field full"><label>NOTE</label><textarea name="notes">' + esc(t.notes || "") + '</textarea></div><div class="field"><label><input name="isTransfer" type="checkbox" style="width:auto" ' + (t.isTransfer ? "checked" : "") + '> Transfer / exclude</label></div><div class="field"><label><input name="flagged" type="checkbox" style="width:auto" ' + (t.flagged ? "checked" : "") + '> Flag for later</label></div><div class="field full"><button class="button primary">Save</button> <button type="button" class="button" id="split">Split</button> <button type="button" class="button" id="rule-from">Create rule</button></div></form><hr style="border:0;border-top:1px solid var(--line);margin:26px 0"><h3>Source record</h3><div class="source mono">' + (t.source ? "file " + esc(t.source.fileName) + " · row " + t.source.rowNumber + "\nraw " + esc(t.source.rawJson) + "\nsha " + esc(t.source.contentSha256) : "No imported source.") + '</div><h3 style="margin-top:26px">Audit trail</h3><ul class="audit">' + t.auditTrail.map((a) => '<li><span class="mono">' + new Date(a.createdAt).toLocaleString() + '</span> · ' + esc(a.action) + '</li>').join("") + '</ul></div>';
  document.body.append(node); node.querySelector("[data-close]").onclick = closeOverlay;
  node.querySelector("#tx-form").onsubmit = async (e) => { e.preventDefault(); const f = new FormData(e.target); await request("/api/transactions/" + id,{method:"PATCH",body:JSON.stringify({merchantName:f.get("merchantName"),categoryId:f.get("categoryId"),notes:f.get("notes"),isTransfer:f.has("isTransfer"),flagged:f.has("flagged")})}); closeOverlay(); toast("Transaction saved"); render(); };
  node.querySelector("#rule-from").onclick = () => openRule({matchText:t.originalDescription,merchantName:t.merchantName,categoryId:t.categoryId});
  node.querySelector("#split").onclick = () => openSplit(t);
}
function openSplit(t) {
  const first = Math.trunc(t.amountMinor / 2), second = t.amountMinor - first;
  const splits = t.splits?.length >= 2 ? t.splits.map((split) => ({ categoryId:split.categoryId, amountMinor:split.amountMinor })) : [{ categoryId:"", amountMinor:first },{ categoryId:"", amountMinor:second }];
  const node = modal("Split transaction", '<form id="split-form"><div id="split-rows"></div><button type="button" class="button" id="add-split">+ Add split</button></form>', async (modalNode) => { const parts = [...modalNode.querySelectorAll(".split-row")].map((row) => ({ categoryId:row.querySelector("select").value, amountMinor:Math.round(Number(row.querySelector("input").value)*100) })); await request("/api/transactions/" + t.id + "/splits",{method:"PUT",body:JSON.stringify({splits:parts})}); closeOverlay(); toast("Split saved"); render(); }, "Save split");
  const draw = () => { node.querySelector("#split-rows").innerHTML = splits.map((split,index) => '<div class="split-row"><div class="field"><label>CATEGORY ' + (index+1) + '</label><select required>' + categoryOptions(split.categoryId) + '</select></div><div class="field"><label>AMOUNT</label><input type="number" step=".01" required value="' + (split.amountMinor/100).toFixed(2) + '"></div><button type="button" class="button danger delete-split" data-index="' + index + '" ' + (splits.length <= 2 ? "disabled" : "") + '>Delete</button></div>').join(""); node.querySelectorAll(".delete-split").forEach((button) => button.onclick = () => { splits.splice(Number(button.dataset.index),1); draw(); }); };
  node.querySelector("#add-split").onclick = () => { splits.push({ categoryId:"", amountMinor:0 }); draw(); };
  draw();
}

async function accounts() {
  const rows = state.accounts.map((a) => '<tr class="account-row" data-id="' + a.id + '"><td><div class="merchant">' + accountEditButton("name",a.name,a.name) + '</div><div class="raw">' + accountEditButton("institution",a.institution,a.institution || "Add institution") + '</div></td><td><div>' + accountEditButton("type",a.type,accountTypes.find(([value])=>value===a.type)?.[1] || a.type,"type") + '</div><div class="raw">' + accountEditButton("lastFour",a.lastFour,a.lastFour ? "···"+a.lastFour : "Add last four","lastFour") + '</div></td><td>' + accountEditButton("role",a.role,a.role,"role") + '</td><td><div class="amount">' + accountEditButton("balanceMinor",a.balanceMinor,a.balanceMinor == null ? "Add balance" : cash(a.balanceMinor,a.currency),"balance") + '</div><div class="raw">' + accountEditButton("balanceAsOf",a.balanceAsOf,a.balanceAsOf ? "as of "+date(a.balanceAsOf) : "Add as-of date","date") + '</div></td><td class="mono">' + date(a.lastImport) + '<div class="raw">' + a.transactionCount + ' transactions</div></td><td><div class="account-actions" hidden><button class="button primary save-account">Save</button><button class="button link cancel-account">Cancel</button></div></td></tr>').join("");
  app.innerHTML = shell('<main class="page"><div class="toolbar" style="justify-content:flex-end"><button class="button primary" id="add-account">Add account</button></div><section class="panel">' + (rows ? '<div class="table-wrap"><table class="accounts-table"><thead><tr><th>Account</th><th>Type / last four</th><th>Role in plan</th><th>Balance / as of</th><th>Activity</th><th></th></tr></thead><tbody>' + rows + '</tbody></table></div>' : '<div class="empty"><h2>No accounts yet.</h2><p>Create the account that owns your first CSV.</p><button class="button primary" id="empty-account">Add account</button></div>') + '</section></main>', "accounts · " + state.accounts.length);
  document.querySelector("#add-account")?.addEventListener("click", openAccount); document.querySelector("#empty-account")?.addEventListener("click", openAccount);
  document.querySelectorAll(".account-field").forEach((field) => field.onclick = () => { const row=field.closest(".account-row"), kind=field.dataset.kind, editor=document.createElement(kind==="role"||kind==="type"?"select":"input"); editor.className="account-editor";editor.dataset.field=field.dataset.field;if(kind==="role")editor.innerHTML=roleOptions(field.dataset.value);else if(kind==="type")editor.innerHTML=selectOptions(accountTypes,field.dataset.value);else{editor.type=kind==="balance"?"number":kind==="date"?"date":"text";editor.value=kind==="balance"&&field.dataset.value!==""?(Number(field.dataset.value)/100).toFixed(2):field.dataset.value;if(kind==="balance")editor.step=".01";if(kind==="lastFour")editor.maxLength=4;} field.replaceWith(editor);row.querySelector(".account-actions").hidden=false;editor.focus(); });
  document.querySelectorAll(".cancel-account").forEach((button)=>button.onclick=()=>accounts());
  document.querySelectorAll(".save-account").forEach((button) => button.onclick = async () => { const row=button.closest(".account-row"), changes={}; row.querySelectorAll(".account-editor").forEach((editor)=>{let value=editor.value;if(editor.dataset.field==="balanceMinor")value=value===""?null:Math.round(Number(value)*100);if(editor.dataset.field==="balanceAsOf")value=value||null;changes[editor.dataset.field]=value}); if(changes.name!==undefined&&!changes.name.trim()){toast("Account name is required");return;} button.disabled=true; try { await request("/api/accounts/"+row.dataset.id,{method:"PATCH",body:JSON.stringify(changes)}); toast("Account saved"); await shared(); accounts(); } catch(error) { button.disabled=false; toast(error.message); } });
}
function openAccount() {
  modal("Add account", '<form id="account-form" class="form-grid"><div class="field full"><label>ACCOUNT NAME</label><input name="name" required placeholder="Chase Checking"></div><div class="field"><label>INSTITUTION</label><input name="institution"></div><div class="field"><label>LAST FOUR</label><input name="lastFour" maxlength="4"></div><div class="field"><label>TYPE</label><select name="type">' + selectOptions(accountTypes) + '</select></div><div class="field"><label>ROLE</label><select name="role">' + roleOptions() + '</select></div><div class="field"><label>BALANCE</label><input name="balance" type="number" step=".01"></div><div class="field"><label>AS OF</label><input name="balanceAsOf" type="date"></div></form>', async () => { const d = Object.fromEntries(new FormData(document.querySelector("#account-form"))); d.balanceMinor = d.balance ? Math.round(Number(d.balance)*100) : null; delete d.balance; await request("/api/accounts",{method:"POST",body:JSON.stringify(d)}); closeOverlay(); toast("Account added"); render(); }, "Add account");
}

const monthLabel = (month) => new Date(month + "-01T00:00:00").toLocaleDateString("en-US", { month:"long", year:"numeric" });
async function budget() {
  state.budgetMonth ||= new Date().toISOString().slice(0,7);
  const data = await request("/api/budget?month=" + state.budgetMonth);
  const spendingGroups = data.groups.filter((group) => group.kind === "expense" && group.id !== "irregular-expenses");
  const incomeGroups = data.groups.filter((group) => group.kind === "income");
  const budgetRows = (groups, income = false) => groups.map((group) => {
    const categoryRows = group.categories.map((c) => { const favorable = income ? c.deltaMinor >= 0 : c.deltaMinor <= 0; return '<tr><td><a class="button link merchant" href="#category/' + c.id + '">' + esc(c.name) + '</a><span class="raw" style="display:inline;margin-left:6px">' + esc(c.cadence) + '</span></td><td class="amount">' + cash(c.budgetMinor) + '</td><td class="amount">' + cash(c.actualMinor) + '</td><td class="amount ' + (favorable ? "green" : "amber") + '">' + (c.deltaMinor > 0 ? "+" : "") + cash(c.deltaMinor) + '</td><td><div class="pace"><span style="width:' + Math.min(100, c.budgetMinor ? c.actualMinor / c.budgetMinor * 100 : 0) + '%"></span></div></td><td class="amount muted">' + cash(c.average12Minor) + '</td></tr>'; }).join("");
    return '<tr class="group-row"><td>' + (income ? "Projected " : "") + esc(group.name) + ' · ' + group.categories.length + ' categories</td><td class="amount">' + cash(group.budgetMinor) + '</td><td class="amount">' + cash(group.actualMinor) + '</td><td class="amount">' + cash(group.actualMinor-group.budgetMinor) + '</td><td></td><td class="amount">' + cash(group.average12Minor) + '</td></tr>' + categoryRows;
  }).join("");
  const groupRows = budgetRows(incomeGroups, true) + budgetRows(spendingGroups);
  const delta = data.summary.spendingDeltaMinor;
  app.innerHTML = shell('<div class="budget-nav"><button class="button link" id="previous-month">◀</button><strong>' + monthLabel(data.month) + '</strong><button class="button link" id="next-month">▶</button><span></span><a class="button" href="#recurring">Recurring</a><a class="button" href="#irregular">Irregular</a><a class="button" href="#budget-settings">Configure</a></div><div class="stats budget-stats"><div class="stat narrative"><span class="label">' + esc(data.month) + '</span><strong>Spending is ' + cash(Math.abs(delta)) + (delta > 0 ? " over" : " under") + ' plan.</strong><p class="muted">Transfers and savings remain separate from spending.</p></div><div class="stat"><span class="label">SPENDING</span><strong>' + cash(data.summary.spendingMinor) + '</strong><span class="mono">budget ' + cash(data.summary.spendingBudgetMinor) + '</span></div><div class="stat"><span class="label">INCOME RECEIVED</span><strong>' + cash(data.summary.incomeMinor) + '</strong><span class="mono">classified income</span></div><div class="stat"><span class="label">SAVED</span><strong>' + cash(data.summary.savedMinor) + '</strong><span class="mono">not spending</span></div><div class="stat"><span class="label">TRANSFERS MOVED</span><strong>' + cash(data.summary.transferMinor) + '</strong><span class="mono">never counted as spend</span></div></div><main class="page"><div class="split-grid"><section class="panel"><div class="table-wrap"><table><thead><tr><th>Category</th><th class="amount">Budget</th><th class="amount">Actual</th><th class="amount">Δ</th><th>Pace</th><th class="amount">12-mo</th></tr></thead><tbody>' + groupRows + '<tr class="group-row"><td>Spending total</td><td class="amount">' + cash(data.summary.spendingBudgetMinor) + '</td><td class="amount">' + cash(data.summary.spendingMinor) + '</td><td class="amount">' + cash(delta) + '</td><td></td><td></td></tr></tbody></table></div></section><aside class="side-stack"><div class="card"><h3>Worth a decision</h3><p class="muted">Categories without a budget or running above their recent average deserve review. Open any category to inspect history and adjust its budget.</p></div><div class="card"><h3>Actual vs. plan</h3><div class="mini-bars">' + spendingGroups.map((group) => '<div title="' + esc(group.name) + '"><span style="height:' + Math.max(8,Math.min(100,group.actualMinor/Math.max(group.budgetMinor,1)*70)) + '%"></span></div>').join("") + '</div></div><div class="card dark"><span class="eyebrow">FEEDS THE PLAN</span><h2>Monthly spending frame ' + cash(data.summary.spendingBudgetMinor * 12) + '.</h2><p>Phase 3 will combine this frame with irregular requirements.</p></div></aside></div></main>', 'budget · ' + monthLabel(data.month));
  document.querySelector("#previous-month").onclick = () => { state.budgetMonth=data.previousMonth; budget(); };
  document.querySelector("#next-month").onclick = () => { state.budgetMonth=data.nextMonth; budget(); };
  document.querySelector(".budget-nav span").insertAdjacentHTML("afterend", '<button class="button primary" id="new-budget">New budget</button>');
  document.querySelector("#new-budget").onclick = openNewBudget;
}

async function openNewBudget() {
  const groups = await request("/api/planning-groups");
  const budgetGroups = groups.filter((group) => group.kind === "expense" || group.kind === "income");
  modal("Create a new budget", '<form id="new-budget-form" class="form-grid"><div class="field full"><label>NAME</label><input name="name" required placeholder="Paycheck or Childcare"></div><div class="field"><label>PLANNING GROUP</label><select name="planningGroupId">' + budgetGroups.map((group) => '<option value="' + group.id + '">' + esc(group.name) + '</option>').join("") + '</select></div><div class="field"><label>CADENCE</label><select name="cadence"><option value="monthly">monthly</option><option value="annual">annual</option><option value="irregular">irregular</option></select></div><div class="field"><label>MONTHLY AMOUNT</label><input name="amount" type="number" min="0" step=".01" required></div><div class="field"><label>EFFECTIVE FROM</label><input name="effectiveFrom" type="month" value="' + (state.budgetMonth || new Date().toISOString().slice(0,7)) + '" required></div><div class="field full"><label>NOTE</label><input name="note" placeholder="Why this projection exists"></div></form>', async (modalNode) => {
    const values = Object.fromEntries(new FormData(modalNode.querySelector("#new-budget-form")));
    const category = await request("/api/categories", { method:"POST", body:JSON.stringify({ name:values.name, planningGroupId:values.planningGroupId, cadence:values.cadence }) });
    try {
      await request("/api/budgets", { method:"POST", body:JSON.stringify({ categoryId:category.id, amountMinor:Math.round(Number(values.amount)*100), effectiveFrom:values.effectiveFrom, note:values.note }) });
    } catch (error) {
      await request("/api/categories/" + category.id, { method:"DELETE" });
      throw error;
    }
    closeOverlay(); toast("Budget created"); await shared(); state.budgetMonth=values.effectiveFrom; budget();
  }, "Create budget");
}

async function categoryDetail(id) {
  state.budgetMonth ||= new Date().toISOString().slice(0,7);
  const data = await request("/api/categories/" + id + "/budget?month=" + state.budgetMonth);
  const isIncome = data.kind === "income";
  const max = Math.max(...data.history.map((item) => item.actualMinor), 1);
  const chart = data.history.map((item) => '<div class="chart-column"><span class="chart-value">' + Math.round(item.actualMinor/100) + '</span><div class="chart-bar ' + ((!isIncome && item.actualMinor > item.budgetMinor && item.budgetMinor) || (isIncome && item.actualMinor < item.budgetMinor) ? "over" : "") + '" style="height:' + Math.max(3,item.actualMinor/max*100) + '%"></div><span>' + item.month.slice(5) + '</span></div>').join("");
  const transactionsRows = data.transactions.map((t) => '<tr><td class="mono">' + date(t.postedDate) + '</td><td>' + esc(t.merchantName || t.originalDescription) + '</td><td class="amount">' + cash(t.amountMinor) + '</td></tr>').join("");
  const budgets = data.budgets.map((b) => '<tr><td>' + esc(b.cadence) + '</td><td class="amount">' + cash(b.amountMinor) + '</td><td class="mono">' + esc(b.effectiveFrom) + (b.effectiveTo ? " → " + esc(b.effectiveTo) : " forward") + '</td><td>' + esc(b.note || "") + '</td><td><button class="button danger delete-budget" data-id="' + b.id + '">Delete</button></td></tr>').join("");
  app.innerHTML = shell('<div class="category-hero"><div><span class="eyebrow">' + esc(data.planningGroupName) + ' · ' + esc(data.cadence) + '</span><h1>' + esc(data.name) + '</h1><p class="muted">' + data.offPlanMonths + ' of 12 months ' + (isIncome ? 'below projection.' : 'over budget.') + '</p></div><div><span class="eyebrow">THIS MONTH</span><strong>' + cash(data.current.actualMinor) + ' <small>/ ' + cash(data.current.budgetMinor) + '</small></strong></div><div><span class="eyebrow">AVERAGES</span><strong>' + cash(data.averages.twelveMonthMinor) + '</strong><p class="mono">12 mo · 6 mo ' + cash(data.averages.sixMonthMinor) + ' · 3 mo ' + cash(data.averages.threeMonthMinor) + '</p></div></div><main class="page"><div class="split-grid"><section class="side-stack"><div class="panel"><div class="panel-head"><span>Actual vs. ' + (isIncome ? 'projection' : 'budget') + ', 12 months</span><span class="mono">bar = actual</span></div><div class="history-chart">' + chart + '</div></div><div class="panel"><div class="panel-head"><span>This month\'s transactions</span><span class="mono">' + data.current.transactionCount + ' records</span></div>' + (transactionsRows ? '<table><thead><tr><th>Date</th><th>Merchant</th><th class="amount">Amount</th></tr></thead><tbody>' + transactionsRows + '</tbody></table>' : '<div class="empty"><p>No transactions this month.</p></div>') + '</div></section><aside class="side-stack"><div class="card"><h3>Add a ' + (isIncome ? 'projection' : 'budget') + '</h3><form id="budget-form" class="form-grid"><div class="field"><label>MONTHLY AMOUNT</label><input name="amount" type="number" min="0" step=".01" required></div><div class="field"><label>EFFECTIVE FROM</label><input name="effectiveFrom" type="month" value="' + state.budgetMonth + '" required></div><div class="field"><label>END MONTH (OPTIONAL)</label><input name="effectiveTo" type="month"></div><div class="field"><label>NOTE</label><input name="note" placeholder="Why this changed"></div><div class="field full"><button class="button primary">Add ' + (isIncome ? 'projection' : 'budget') + '</button></div></form></div><div class="panel"><div class="panel-head"><span>Existing ' + (isIncome ? 'projections' : 'budgets') + '</span><span class="mono">' + data.budgets.length + ' records</span></div>' + (budgets ? '<div class="table-wrap"><table><thead><tr><th>Cadence</th><th class="amount">Amount</th><th>Effective</th><th>Note</th><th></th></tr></thead><tbody>' + budgets + '</tbody></table></div>' : '<div class="empty"><p>No records yet. Add the first one above.</p></div>') + '</div></aside></div></main>', 'Budget / ' + data.name);
  document.querySelector("#budget-form").onsubmit = async (event) => { event.preventDefault(); const f=new FormData(event.target); await request("/api/budgets",{method:"POST",body:JSON.stringify({categoryId:id,amountMinor:Math.round(Number(f.get("amount"))*100),effectiveFrom:f.get("effectiveFrom"),effectiveTo:f.get("effectiveTo")||null,note:f.get("note")})}); toast("Budget added"); categoryDetail(id); };
  document.querySelectorAll(".delete-budget").forEach((button) => button.onclick = async () => { if (!confirm("Delete this budget record? Transaction history will not be changed.")) return; await request("/api/budgets/"+button.dataset.id,{method:"DELETE"}); toast("Budget deleted"); categoryDetail(id); });
  document.querySelector(".category-hero > div").insertAdjacentHTML("beforeend", '<button class="button danger" id="delete-category">Delete budget</button>');
  document.querySelector("#delete-category").onclick = async () => {
    if (!confirm("Delete this entire budget category and all of its budget amounts? This cannot be undone.")) return;
    await request("/api/categories/" + id, { method:"DELETE" });
    toast("Budget deleted"); await shared(); location.hash="budget"; render();
  };
}

async function recurring() {
  const data = await request("/api/recurring");
  const candidates = data.candidates.map((item) => '<div class="recurring-row"><div><strong>' + esc(item.merchantName) + '</strong><div class="raw">' + item.hitCount + ' hits · ' + item.monthCount + ' months</div></div><div class="amount">' + cash(item.averageMinor) + '</div><div class="mono">monthly?</div><div class="' + (item.confidence==="high"?"green":"amber") + '">confidence ' + item.confidence + '<div class="raw">variance ' + item.variancePercent + '%</div></div><div><button class="button primary recurring-decision" data-state="confirmed" data-merchant="' + esc(item.merchantName) + '" data-merchant-id="' + (item.merchantId||"") + '" data-category="' + (item.categoryId||"") + '" data-amount="' + item.averageMinor + '">Confirm</button> <button class="button recurring-decision" data-state="dismissed" data-merchant="' + esc(item.merchantName) + '" data-merchant-id="' + (item.merchantId||"") + '" data-category="' + (item.categoryId||"") + '" data-amount="' + item.averageMinor + '">Not recurring</button></div></div>').join("");
  const confirmed = data.confirmed.map((item) => '<tr><td class="merchant">' + esc(item.merchantName) + '</td><td class="amount">' + cash(item.amountMinor) + '</td><td class="mono">' + esc(item.cadence) + '</td><td>' + esc(item.nextDueDate||"—") + '</td><td>' + esc(item.categoryName||"Uncategorized") + '</td></tr>').join("");
  const monthly = data.confirmed.filter((item)=>item.cadence==="monthly").reduce((sum,item)=>sum+item.amountMinor,0);
  app.innerHTML = shell('<div class="stats"><div class="stat narrative"><span class="label">RECURRING COMMITMENTS</span><strong>' + cash(monthly) + ' a month is confirmed.</strong><p>' + data.candidates.length + ' detected patterns need a verdict.</p></div><div class="stat"><span class="label">MONTHLY RECURRING</span><strong>' + cash(monthly) + '</strong></div><div class="stat"><span class="label">CONFIRMED</span><strong>' + data.confirmed.length + '</strong></div><div class="stat"><span class="label">TO REVIEW</span><strong>' + data.candidates.length + '</strong></div></div><main class="page"><div class="split-grid"><section class="side-stack"><div class="panel"><div class="panel-head"><span>Needs review · ' + data.candidates.length + ' detected patterns</span><span class="mono">nothing enters the budget until confirmed</span></div>' + (candidates || '<div class="empty"><h2>No patterns need review.</h2><p>Bloom needs at least three charges from a merchant before suggesting a pattern.</p></div>') + '</div><div class="panel"><div class="panel-head"><span>Confirmed recurring</span><span class="mono">' + data.confirmed.length + '</span></div>' + (confirmed ? '<table><thead><tr><th>Merchant</th><th class="amount">Amount</th><th>Cadence</th><th>Next due</th><th>Category</th></tr></thead><tbody>' + confirmed + '</tbody></table>' : '<div class="empty"><p>No confirmed recurring items yet.</p></div>') + '</div></section><aside class="side-stack"><div class="card"><h3>How detection works</h3><p class="muted">Three or more charges from the same merchant become a candidate. Stable amounts across several months receive higher confidence.</p></div><a class="button" href="#budget">Back to budget</a></aside></div></main>', 'recurring · ' + data.confirmed.length + ' confirmed · ' + data.candidates.length + ' to review');
  document.querySelectorAll(".recurring-decision").forEach((button) => button.onclick = async () => { await request("/api/recurring/decision",{method:"POST",body:JSON.stringify({merchantId:button.dataset.merchantId,merchantName:button.dataset.merchant,categoryId:button.dataset.category,amountMinor:Number(button.dataset.amount),cadence:"monthly",state:button.dataset.state})}); toast(button.dataset.state==="confirmed"?"Recurring item confirmed":"Pattern dismissed"); recurring(); });
}

async function irregular() {
  const data = await request("/api/irregular");
  const rows = data.categories.map((item) => { const short=Math.max(0,Number(item.targetBalanceMinor||0)-Number(item.currentBalanceMinor||0)); return '<tr class="irregular-row" data-id="' + item.id + '"><td><div class="merchant">' + esc(item.name) + '</div><div class="pace"><span style="width:' + Math.min(100,Number(item.currentBalanceMinor||0)/Math.max(Number(item.targetBalanceMinor||1),1)*100) + '%"></span></div></td><td class="mono">' + esc(item.cadence) + '</td><td class="amount">' + cash(item.currentBalanceMinor) + ' / ' + cash(item.targetBalanceMinor) + '</td><td class="amount amber">' + (short?cash(short):"—") + '</td><td class="amount">' + cash(item.annualExpectedMinor) + '</td><td>' + esc(item.nextDueDate||"—") + '</td><td><button class="button edit-irregular" data-id="' + item.id + '">Edit</button> <button class="button danger delete-irregular" data-id="' + item.id + '" data-name="' + esc(item.name) + '">Delete</button></td></tr>'; }).join("");
  const short=Math.max(0,data.summary.targetMinor-data.summary.heldMinor);
  app.innerHTML = shell('<div class="stats"><div class="stat narrative"><span class="label">IRREGULAR EXPENSES</span><strong>Targets, not fictional monthly budgets.</strong><p>Balances show whether the household is ready.</p></div><div class="stat"><span class="label">RESERVE BALANCES</span><strong>' + cash(data.summary.heldMinor) + '</strong><span class="mono">' + cash(short) + ' short</span></div><div class="stat"><span class="label">SPENT THIS YEAR</span><strong>' + cash(data.summary.spentMinor) + '</strong><span class="mono">' + cash(data.summary.expectedMinor) + ' expected</span></div></div><main class="page"><div class="split-grid"><section class="panel"><div class="table-wrap"><table><thead><tr><th>Category</th><th>Cadence</th><th class="amount">Held / target</th><th class="amount">Short</th><th class="amount">Annual draw</th><th>Next due</th><th></th></tr></thead><tbody>' + rows + '<tr class="group-row"><td>All irregular</td><td></td><td class="amount">' + cash(data.summary.heldMinor) + ' / ' + cash(data.summary.targetMinor) + '</td><td class="amount">' + cash(short) + '</td><td class="amount">' + cash(data.summary.expectedMinor) + '</td><td></td><td></td></tr></tbody></table></div></section><aside class="side-stack"><div class="card"><h3>First-class irregular costs</h3><p class="muted">Set a target balance, current amount held, expected annual draw, and next known due date for each category.</p></div><div class="card dark"><span class="eyebrow">THE RULE</span><h2>Target balances first. Replenishment rate second.</h2></div></aside></div></main>', 'irregular · ' + data.categories.length + ' categories');
  document.querySelectorAll(".edit-irregular").forEach((button)=>button.onclick=()=>editIrregular(data.categories.find((item)=>item.id===button.dataset.id)));
  document.querySelectorAll(".delete-irregular").forEach((button)=>button.onclick=async()=>{if(!confirm('Delete the irregular budget "'+button.dataset.name+'" and all of its budget amounts? This cannot be undone.'))return;await request("/api/categories/"+button.dataset.id,{method:"DELETE"});toast("Irregular budget deleted");await shared();irregular();});
}
function editIrregular(item) {
  modal("Edit " + item.name, '<form id="irregular-form" class="form-grid"><div class="field"><label>TARGET BALANCE</label><input name="target" type="number" step=".01" value="' + (Number(item.targetBalanceMinor||0)/100).toFixed(2) + '"></div><div class="field"><label>CURRENTLY HELD</label><input name="current" type="number" step=".01" value="' + (Number(item.currentBalanceMinor||0)/100).toFixed(2) + '"></div><div class="field"><label>EXPECTED ANNUAL DRAW</label><input name="expected" type="number" step=".01" value="' + (Number(item.annualExpectedMinor||0)/100).toFixed(2) + '"></div><div class="field"><label>NEXT DUE</label><input name="nextDueDate" type="date" value="' + esc(item.nextDueDate||"") + '"></div></form>', async()=>{const f=new FormData(document.querySelector("#irregular-form"));await request("/api/categories/"+item.id,{method:"PATCH",body:JSON.stringify({targetBalanceMinor:Math.round(Number(f.get("target"))*100),currentBalanceMinor:Math.round(Number(f.get("current"))*100),annualExpectedMinor:Math.round(Number(f.get("expected"))*100),nextDueDate:f.get("nextDueDate")||null,cadence:"irregular"})});closeOverlay();toast("Irregular target saved");irregular();},"Save targets");
}

async function budgetSettings() {
  const settings=await request("/api/budget-settings");
  const groupCounts={};state.categories.forEach((item)=>groupCounts[item.planningGroupName]=(groupCounts[item.planningGroupName]||0)+1);
  app.innerHTML=shell('<main class="page"><div class="split-grid"><section class="side-stack"><div class="card"><h3>How budgets are set by default</h3><p><strong>Fixed / contractual</strong><span class="mono" style="float:right">confirmed recurring amount</span></p><hr><p><strong>Essential variable</strong><span class="mono" style="float:right">trailing average</span></p><hr><p><strong>Lifestyle / discretionary</strong><span class="mono" style="float:right">manual</span></p><hr><p><strong>Irregular</strong><span class="mono" style="float:right">balance-funded</span></p></div><div class="card"><h3>Spending, transfers and savings</h3><p><strong>Spending</strong> · Money leaving the household and assigned to an expense category.</p><p><strong>Transfers</strong> · Movement between household accounts; excluded from spend and income.</p><p><strong>Savings</strong> · Capacity tracked separately from spending.</p></div></section><aside class="side-stack"><div class="card"><h3>Period and rollover</h3><form id="settings-form" class="form-grid"><div class="field full"><label>BUDGET PERIOD</label><select name="period"><option value="calendar-month" '+(settings.period==="calendar-month"?"selected":"")+'>Calendar month</option><option value="paycheck-cycle" '+(settings.period==="paycheck-cycle"?"selected":"")+'>Paycheck cycle</option></select></div><div class="field"><label>AVERAGES WINDOW</label><select name="averageWindow"><option value="3" '+(settings.averageWindow===3?"selected":"")+'>3 months</option><option value="6" '+(settings.averageWindow===6?"selected":"")+'>6 months</option><option value="12" '+(settings.averageWindow===12?"selected":"")+'>12 months</option></select></div><div class="field"><label><input name="rollover" type="checkbox" style="width:auto" '+(settings.rollover?"checked":"")+'> Unspent budget rolls over</label></div><div class="field full"><button class="button primary">Save configuration</button></div></form></div><div class="panel"><div class="panel-head">Planning groups</div><table><thead><tr><th>Group</th><th class="amount">Categories</th></tr></thead><tbody>'+Object.entries(groupCounts).map(([name,count])=>'<tr><td>'+esc(name)+'</td><td class="amount">'+count+'</td></tr>').join("")+'</tbody></table></div><div class="card dark"><span class="eyebrow">EFFECT OF THESE SETTINGS</span><h2>Budget behavior stays explicit and reviewable.</h2></div></aside></div></main>','Budget / configuration');
  document.querySelector("#settings-form").onsubmit=async(event)=>{event.preventDefault();const f=new FormData(event.target);await request("/api/budget-settings",{method:"PATCH",body:JSON.stringify({period:f.get("period"),averageWindow:Number(f.get("averageWindow")),rollover:f.has("rollover")})});toast("Budget configuration saved");budgetSettings();};
}

async function categories() {
  const groups = {}; state.categories.forEach((c) => (groups[c.planningGroupName] ||= []).push(c));
  const rows = Object.entries(groups).map(([name,list]) => '<tr class="group-row"><td colspan="5">' + esc(name) + '</td></tr>' + list.map((c) => '<tr><td class="merchant">' + esc(c.name) + '</td><td class="mono">' + esc(c.planningGroupName) + '</td><td><select class="cadence" data-id="' + c.id + '"><option value="monthly" ' + (c.cadence==="monthly"?"selected":"") + '>monthly</option><option value="annual" ' + (c.cadence==="annual"?"selected":"") + '>annual</option><option value="irregular" ' + (c.cadence==="irregular"?"selected":"") + '>irregular</option></select></td><td class="mono">' + c.transactionCount + '</td><td class="amount">' + cash(c.spendingMinor) + '</td></tr>').join("")).join("");
  app.innerHTML = shell('<main class="page"><div class="split-grid"><section class="panel"><div class="table-wrap"><table><thead><tr><th>Category</th><th>Planning group</th><th>Cadence</th><th>Transactions</th><th class="amount">Actual</th></tr></thead><tbody>' + rows + '</tbody></table></div></section><aside class="side-stack"><div class="card"><h3>Why cadence matters</h3><p class="muted">Monthly activity supports recurring requirements. Irregular activity remains distinct for future reserve planning.</p></div><div class="card dark"><span class="eyebrow">DOWNSTREAM</span><h2>Category meaning travels with every transaction.</h2><p>Planning calculations remain separate until Phase 3.</p></div></aside></div></main>', "categories · " + state.categories.length + " active");
  document.querySelectorAll(".cadence").forEach((s) => s.onchange = async () => { await request("/api/categories/" + s.dataset.id,{method:"PATCH",body:JSON.stringify({cadence:s.value})}); toast("Cadence saved"); });
}

async function rules() {
  const items = await request("/api/rules"); const rows = items.map((r) => '<tr><td class="mono">' + String(r.priority).padStart(2,"0") + '</td><td><span class="mono">' + esc(r.matchType) + '</span> <strong>' + esc(r.matchText) + '</strong></td><td>' + (r.merchantName ? "Merchant → " + esc(r.merchantName) : "") + (r.categoryName ? " · Category → " + esc(r.categoryName) : "") + (r.markTransfer ? "Mark transfer" : "") + '</td><td class="mono">' + r.matchCount + '</td><td class="mono">' + (r.lastHitAt ? new Date(r.lastHitAt).toLocaleDateString() : "never") + '</td><td><button class="button danger delete-rule" data-id="' + esc(r.id) + '">Delete</button></td></tr>').join("");
  app.innerHTML = shell('<main class="page"><div class="toolbar" style="justify-content:flex-end"><button class="button" id="run-rules">Run rules</button><button class="button primary" id="new-rule">New rule</button></div><section class="panel">' + (rows ? '<div class="table-wrap"><table><thead><tr><th>#</th><th>When raw text</th><th>Then</th><th>Matches</th><th>Last hit</th><th></th></tr></thead><tbody>' + rows + '</tbody></table></div>' : '<div class="empty"><h2>No rules yet.</h2><p>First match wins across all transactions. Manual edits remain authoritative.</p><button class="button primary" id="empty-rule">Create first rule</button></div>') + '</section></main>', items.length + " rules · all transactions");
  document.querySelector("#run-rules")?.addEventListener("click", openRuleRunner); document.querySelector("#new-rule")?.addEventListener("click", () => openRule()); document.querySelector("#empty-rule")?.addEventListener("click", () => openRule());
  document.querySelectorAll(".delete-rule").forEach((button) => button.onclick = async () => { if (!confirm("Delete this rule? Existing transactions will not be changed.")) return; await request("/api/rules/" + button.dataset.id,{method:"DELETE"}); toast("Rule deleted"); rules(); });
}
function openRule(seed = {}) {
  closeOverlay(); modal("Create classification rule", '<form id="rule-form" class="form-grid"><div class="field"><label>MATCH TYPE</label><select name="matchType"><option value="contains">contains</option><option value="starts-with">starts with</option><option value="equals">equals</option><option value="regex">regex</option></select></div><div class="field"><label>RAW TEXT</label><input name="matchText" required value="' + esc(seed.matchText || "") + '"></div><div class="field"><label>MERCHANT</label><input name="merchantName" value="' + esc(seed.merchantName || "") + '"></div><div class="field"><label>CATEGORY</label><select name="categoryId">' + categoryOptions(seed.categoryId) + '</select></div><div class="field"><label><input name="markTransfer" type="checkbox" style="width:auto"> Mark as transfer</label></div><div class="field"><span class="mono">Applies to matching transactions in every account.</span></div></form>', async () => { const f = document.querySelector("#rule-form"), d = Object.fromEntries(new FormData(f)); d.markTransfer = new FormData(f).has("markTransfer"); await request("/api/rules",{method:"POST",body:JSON.stringify(d)}); closeOverlay(); toast("Rule created"); location.hash="rules"; render(); }, "Save rule");
}

function openRuleRunner() {
  const node = document.createElement("div"); node.className = "modal-backdrop";
  node.innerHTML = '<section class="modal wide"><div class="modal-head"><span class="mono">preview first</span><h2>Run classification rules</h2><button data-close>×</button></div><div class="modal-body" id="runner-body"><div class="card"><h3>Choose the transaction scope</h3><p class="muted">Rules run in priority order. The first matching rule wins.</p><p><label><input id="only-uncategorized" type="checkbox" checked style="width:auto"> Only uncategorized transactions</label></p><p><label><input id="overwrite-manual" type="checkbox" style="width:auto"> Replace manual classifications</label></p><p class="mono">Manual classifications are preserved unless you explicitly enable replacement.</p></div></div><div class="modal-actions"><button class="button" data-close>Cancel</button><button class="button primary" id="preview-rules">Preview changes</button></div></section>';
  document.body.append(node); node.querySelectorAll("[data-close]").forEach((button) => button.onclick = closeOverlay);
  node.querySelector("#preview-rules").onclick = async () => {
    try {
      const options = { onlyUncategorized:node.querySelector("#only-uncategorized").checked, overwriteManual:node.querySelector("#overwrite-manual").checked };
      const result = await request("/api/rules/run", { method:"POST", body:JSON.stringify(options) });
      node.dataset.options = JSON.stringify(options);
      const categoryName = (id) => state.categories.find((category) => category.id === id)?.name || id || "Uncategorized";
      const rows = result.changes.slice(0,100).map((change) => '<tr><td class="mono">' + date(change.postedDate) + '</td><td><div class="merchant">' + esc(change.description) + '</div><div class="raw">rule priority ' + change.rulePriority + '</div></td><td>' + esc(change.before.merchantName || change.description) + '<div class="raw">' + esc(categoryName(change.before.categoryId)) + '</div></td><td>' + esc(change.after.merchantName || change.description) + '<div class="raw">' + esc(categoryName(change.after.categoryId)) + '</div></td><td class="amount">' + cash(change.amountMinor) + '</td></tr>').join("");
      node.querySelector("#runner-body").innerHTML = '<div class="stats"><div class="stat"><span class="label">CONSIDERED</span><strong>' + result.summary.considered + '</strong></div><div class="stat"><span class="label">MATCHED</span><strong>' + result.summary.matched + '</strong></div><div class="stat"><span class="label">WILL CHANGE</span><strong class="green">' + result.summary.changed + '</strong></div><div class="stat"><span class="label">MANUAL SKIPPED</span><strong>' + result.summary.skippedManual + '</strong></div></div>' + (rows ? '<section class="panel" style="margin-top:20px"><div class="panel-head"><span>Proposed changes</span><span class="mono">' + result.changes.length + ' total</span></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Raw transaction</th><th>Before</th><th>After</th><th class="amount">Amount</th></tr></thead><tbody>' + rows + '</tbody></table></div></section>' : '<div class="empty"><h2>No changes to apply.</h2><p>No eligible transactions matched a rule that would change their classification.</p></div>');
      const button = node.querySelector("#preview-rules"); button.textContent = result.summary.changed ? "Apply " + result.summary.changed + " changes" : "Nothing to apply"; button.disabled = !result.summary.changed;
      button.onclick = async () => {
        try {
          const applied = await request("/api/rules/run", { method:"POST", body:JSON.stringify({ ...JSON.parse(node.dataset.options), apply:true }) });
          closeOverlay(); toast(applied.summary.changed + " transactions classified"); render();
        } catch (error) { toast(error.message); }
      };
    } catch (error) { toast(error.message); }
  };
}

function openImport() {
  if (!state.accounts.length) { toast("Add an account before importing"); location.hash="accounts"; return; }
  state.files=[]; state.staged=null; const node=document.createElement("div"); node.className="modal-backdrop";
  node.innerHTML='<section class="modal wide"><div class="modal-head"><span class="mono">step 1 of 3</span><h2>Import CSV</h2><button data-close>×</button></div><div class="modal-body" id="import-body"><label class="drop" id="drop"><strong>Drop CSV files here</strong><p class="mono">or browse · several at once · overlapping ranges are safe</p><input id="file-input" type="file" accept=".csv,text/csv" multiple><span class="button">Browse files</span></label><div id="files"></div></div><div class="modal-actions"><button class="button" data-close>Cancel</button><button class="button primary" id="stage" disabled>Map & preview</button></div></section>'; document.body.append(node);
  node.querySelectorAll("[data-close]").forEach((b)=>b.onclick=closeOverlay); const input=node.querySelector("#file-input"),drop=node.querySelector("#drop");
  drop.onclick=()=>input.click(); input.onclick=(e)=>e.stopPropagation(); input.onchange=()=>loadFiles([...input.files]); drop.ondragover=(e)=>{e.preventDefault();drop.classList.add("drag")}; drop.ondragleave=()=>drop.classList.remove("drag"); drop.ondrop=(e)=>{e.preventDefault();drop.classList.remove("drag");loadFiles([...e.dataTransfer.files])}; node.querySelector("#stage").onclick=stageFiles;
}
async function loadFiles(files) {
  state.files=await Promise.all(files.filter(f=>f.name.toLowerCase().endsWith(".csv")).map(async(f)=>{const csv=await f.text(),headerLine=csv.replace(/^\uFEFF/,"").split(/\r?\n/).find(line=>line.trim())||"",headers=headerLine.split(",").map(h=>h.replace(/^"|"$/g,"").trim()),find=(...n)=>headers.find(h=>n.includes(h.toLowerCase()))||"";return{name:f.name,csv,headers,accountId:state.accounts[0].id,mapping:{date:find("date","posted date","transaction date","run date"),description:find("description","merchant","payee","memo","action"),amount:find("amount","amount ($)"),debit:find("debit","withdrawal"),credit:find("credit","deposit"),amountSign:"as-is"}}})); drawFiles();
}
const headerOptions=(f,v,blank=true)=>(blank?'<option value="">Ignore</option>':'')+f.headers.map(h=>'<option value="'+esc(h)+'" '+(h===v?"selected":"")+'>'+esc(h)+'</option>').join("");
function drawFiles(){const list=document.querySelector("#files");list.innerHTML=state.files.map((f,i)=>'<div class="card" style="margin-top:14px"><div class="file-row"><div><strong>'+esc(f.name)+'</strong><div class="raw">'+f.headers.length+' columns</div></div><select class="file-account" data-i="'+i+'">'+accountOptions(f.accountId)+'</select></div><div class="mapping">'+["date","description","amount","debit","credit"].map(k=>'<div class="field"><label>'+k.toUpperCase()+'</label><select class="map" data-i="'+i+'" data-k="'+k+'">'+headerOptions(f,f.mapping[k],k!=="amount")+'</select></div>').join("")+'<div class="field"><label>AMOUNT SIGN</label><select class="map" data-i="'+i+'" data-k="amountSign"><option value="as-is">Keep signs</option><option value="flip">Flip signs</option></select></div></div></div>').join("");document.querySelector("#stage").disabled=!state.files.length;document.querySelectorAll(".file-account").forEach(s=>s.onchange=()=>state.files[s.dataset.i].accountId=s.value);document.querySelectorAll(".map").forEach(s=>s.onchange=()=>state.files[s.dataset.i].mapping[s.dataset.k]=s.value)}
async function stageFiles(){try{const r=await request("/api/imports/stage",{method:"POST",body:JSON.stringify({files:state.files})});state.staged=r;document.querySelector(".modal-head .mono").textContent="step 2 of 3";document.querySelector("#import-body").innerHTML='<div class="stats"><div class="stat"><span class="label">ROWS READ</span><strong>'+r.rowsRead+'</strong></div><div class="stat"><span class="label">NEW</span><strong class="green">'+r.newCount+'</strong></div><div class="stat"><span class="label">DUPLICATES</span><strong>'+r.duplicateCount+'</strong></div><div class="stat"><span class="label">EXCEPTIONS</span><strong class="amber">'+r.exceptionCount+'</strong></div></div><section class="panel" style="margin-top:20px"><div class="table-wrap"><table><thead><tr><th>File / row</th><th>Date</th><th>Description</th><th class="amount">Amount</th><th>Status</th></tr></thead><tbody>'+r.preview.map(x=>'<tr><td class="mono">'+esc(x.fileName)+' · '+x.rowNumber+'</td><td>'+esc(x.postedDate||"—")+'</td><td>'+esc(x.description||"missing")+'</td><td class="amount">'+(x.amountMinor==null?"—":cash(x.amountMinor))+'</td><td><span class="badge '+(x.disposition==="exception"?"warn":"good")+'">'+x.disposition+'</span></td></tr>').join("")+'</tbody></table></div></section>';const old=document.querySelector("#stage"),fresh=old.cloneNode(true);old.replaceWith(fresh);fresh.disabled=false;fresh.textContent="Commit "+r.newCount+" records";fresh.onclick=commitFiles}catch(e){toast(e.message)}}
async function commitFiles(){try{const r=await request("/api/imports/"+state.staged.id+"/commit",{method:"POST",body:JSON.stringify({allowExceptions:true})});closeOverlay();toast(r.committed+" transactions imported");render()}catch(e){toast(e.message)}}

async function history(){const runs=await request("/api/imports");const rows=runs.map(r=>'<tr><td class="mono">'+new Date(r.createdAt).toLocaleString()+'</td><td>'+esc(r.fileNames||"")+'</td><td class="amount">'+r.rowsRead+'</td><td class="amount">'+r.newCount+'</td><td class="amount">'+r.duplicateCount+'</td><td class="amount amber">'+r.exceptionCount+'</td><td><span class="badge">'+r.status+'</span></td></tr>').join("");app.innerHTML=shell('<main class="page"><div class="split-grid"><section class="panel">'+(rows?'<div class="table-wrap"><table><thead><tr><th>Run</th><th>Files</th><th>Rows</th><th>New</th><th>Dupes</th><th>Exceptions</th><th>State</th></tr></thead><tbody>'+rows+'</tbody></table></div>':'<div class="empty"><h2>No imports yet.</h2></div>')+'</section><aside class="cards"><div class="card"><h3>Import guarantees</h3><p class="muted">Every raw row is retained. Exact overlaps are skipped. Ambiguous records remain reviewable.</p></div><button class="button primary" data-action="import">New import</button></aside></div></main>',"import history · "+runs.length+" runs");common()}
const plainCash = (minor) => new Intl.NumberFormat("en-US", { maximumFractionDigits:0 }).format(Math.round(Number(minor || 0) / 100));
const signedCash = (minor) => (minor >= 0 ? "+" : "−") + cash(Math.abs(minor));
const planLinks = [
  ["plan","Overview"],["plan-household","Household requirement"],["plan-income","Required income"],
  ["plan-cash","Cash & reserves"],["plan-sinking","Sinking funds"],["plan-capital","Capacity & growth"],
  ["plan-accounts","Accounts"],["plan-assumptions","Assumptions"]
];
const planNav = (data) => '<div class="plan-nav">'+planLinks.map(([id,label])=>'<a href="#'+id+'" class="'+(state.route===id?'active':'')+'">'+label+'</a>').join('')+'<span>as of '+date(data.asOfDate)+' · '+esc(data.formulaVersion)+'</span></div>';
const planShell = (data, content, meta="") => shell(planNav(data)+content, meta || "Plan / " + (planLinks.find(([id])=>id===state.route)?.[1] || "Overview"));
const meter = (held,target) => '<div class="plan-meter"><span style="width:'+Math.min(100,target ? held/target*100 : 0)+'%"></span></div>';
const traceButton = (result) => '<button class="button link trace" data-result="'+esc(result.resultType)+'">trace</button>';
function bindTraces(data) { document.querySelectorAll('.trace').forEach((button)=>button.onclick=()=>openTrace(data.results[button.dataset.result])); }
function openTrace(value) {
  modal("Source and formula", '<div class="trace-result"><span class="eyebrow">'+esc(value.resultType)+'</span><h2>'+cash(value.amountMinor)+'</h2><p class="mono">'+esc(value.formulaName)+' · '+esc(value.formulaVersion)+'</p></div><div class="source"><strong>Inputs</strong>\n'+value.inputReferences.map((item)=>esc(item.type)+' · '+esc(item.id)+' · '+esc(item.detail ?? '')).join('\n')+'\n\nanchored '+esc(value.asOfDate)+'</div>', async()=>closeOverlay(), "Done");
}
const requirementName = (id) => ({"fixed-contractual":"Fixed / contractual","essential-variable":"Essential variable","lifestyle-discretionary":"Lifestyle / discretionary","irregular-expenses":"Irregular, annualized"})[id] || id;

async function plan(){
  const data=await request('/api/plan'), gap=data.cash.liquidRequirementMinor-data.cash.cashHeldMinor, reserveGap=data.cash.emergencyTargetMinor-data.cash.emergencyHeldMinor;
  const requirements=[
    ["Operating cash",data.cash.operatingHeldMinor,data.cash.operatingTargetMinor,"plan-cash"],
    ["Emergency reserve",data.cash.emergencyHeldMinor,data.cash.emergencyTargetMinor,"plan-cash"],
    ["Known obligations",data.cash.obligationHeldMinor,data.cash.obligationTargetMinor,"plan-cash"],
    ["Sinking funds",data.capital.sinkingHeldMinor,data.capital.sinkingTargetMinor,"plan-sinking"]
  ];
  app.innerHTML=planShell(data,'<section class="plan-hero"><div><span class="eyebrow">PLAN VERDICT</span><h1>'+(data.income.annualNetMinor>=data.totals.householdMinor?'Income clears the household requirement.':'Income is below the household requirement.')+'</h1><p>'+(gap>0?cash(gap)+' of required cash remains unfunded.':'Required cash is fully held.')+'</p></div><div><span>REQUIRED CASH</span><strong>'+plainCash(data.cash.cashHeldMinor)+' / '+plainCash(data.cash.liquidRequirementMinor)+'</strong>'+meter(data.cash.cashHeldMinor,data.cash.liquidRequirementMinor)+'</div><div><span>NET INCOME / REQUIREMENT</span><strong>'+plainCash(data.income.annualNetMinor)+' / '+plainCash(data.totals.householdMinor)+'</strong>'+meter(data.income.annualNetMinor,data.totals.householdMinor)+'</div><div><span>GROWTH CAPITAL</span><strong>'+cash(data.capital.growthCapitalMinor)+'</strong><small>after cash and sinking targets</small></div></section><main class="page"><div class="split-grid"><section class="panel"><div class="panel-head"><span>Balances & gaps</span><span class="mono">target balance first</span></div><table><thead><tr><th>Requirement</th><th class="amount">Held / target</th><th class="amount">Gap</th></tr></thead><tbody>'+requirements.map(([name,held,target,route],i)=>'<tr><td><a href="#'+route+'"><strong>'+String(i+1).padStart(2,'0')+' · '+name+'</strong></a>'+meter(held,target)+'</td><td class="amount">'+cash(held)+' / '+cash(target)+'</td><td class="amount '+(held>=target?'green':'amber')+'">'+(held>=target?'funded':cash(target-held))+'</td></tr>').join('')+'</tbody></table></section><aside class="side-stack"><div class="card dark"><span class="eyebrow">NEXT DOLLAR</span><h2>'+(reserveGap>0?'Build the emergency reserve by '+cash(reserveGap)+'.':'Direct available capacity to unfunded sinking balances, then growth.')+'</h2></div><div class="card"><h3>The model</h3><p>Household requirement <strong class="amount">'+cash(data.totals.householdMinor)+'</strong></p><p>Liquid requirement <strong class="amount">'+cash(data.cash.liquidRequirementMinor)+'</strong></p><p>Savings capacity <strong class="amount">'+cash(data.capital.savingsCapacityMinor)+'</strong></p><p>Growth capital <strong class="amount">'+cash(data.capital.growthCapitalMinor)+'</strong></p>'+traceButton(data.results.growthCapital)+'</div></aside></div></main>', 'Plan · '+data.asOfDate); bindTraces(data);
}

async function planHousehold(){
  const data=await request('/api/plan');
  app.innerHTML=planShell(data,'<section class="plan-hero"><div class="wide"><span class="eyebrow">NORMALIZED ANNUAL SPEND</span><h1>'+cash(data.totals.householdMinor)+' — what this household costs in a normal year.</h1><p>Actual category-months replace budgets as evidence accumulates; explicit irregular targets override both.</p></div><div><span>COMMITTED</span><strong>'+cash(data.totals.committedMinor)+'</strong></div><div><span>LIFESTYLE</span><strong>'+cash(data.totals.lifestyleMinor)+'</strong></div><div><span>IRREGULAR</span><strong>'+cash(data.totals.irregularMinor)+'</strong></div></section><main class="page"><div class="split-grid"><section class="panel"><table><thead><tr><th>Requirement class</th><th class="amount">Annual</th><th class="amount">Monthly</th><th>Derived from</th></tr></thead><tbody>'+data.requirementClasses.map(group=>'<tr><td><strong>'+requirementName(group.id)+'</strong><div class="raw">'+group.categories.map(c=>esc(c.categoryName)).join(', ')+'</div></td><td class="amount">'+cash(group.annualMinor)+'</td><td class="amount">'+cash(Math.round(group.annualMinor/12))+'</td><td class="mono">'+group.categories.map(c=>esc(c.categoryName)+': '+esc(c.source)).join('<br>')+'</td></tr>').join('')+'<tr class="group-row"><td>Household requirement</td><td class="amount">'+cash(data.totals.householdMinor)+'</td><td class="amount">'+cash(Math.round(data.totals.householdMinor/12))+'</td><td>'+traceButton(data.results.householdRequirement)+'</td></tr></tbody></table></section><aside class="card"><h3>Normalization rules</h3><p>Actual activity is used for category-months where it exists. Effective budgets fill the remaining months in each averaging window.</p><p>Any months with neither actuals nor a budget are labeled missing rather than silently treated as evidence.</p><p>Irregular categories use a manual annual expectation when present.</p></aside></div></main>'); bindTraces(data);
}

async function planIncome(){
  const data=await request('/api/plan'), r=data.results;
  app.innerHTML=planShell(data,'<section class="plan-hero"><div><span class="eyebrow">THREE THRESHOLDS</span><h1>Required income is expressed in net and gross, with tax visible.</h1></div><div><span>MINIMUM GROSS</span><strong>'+cash(r.minimumGrossIncome.amountMinor)+'</strong><small>committed + irregular</small></div><div><span>SUSTAINING GROSS</span><strong>'+cash(r.sustainingGrossIncome.amountMinor)+'</strong><small>normalized household plan</small></div><div><span>COMFORTABLE GROSS</span><strong>'+cash(r.comfortableGrossIncome.amountMinor)+'</strong><small>plus savings requirement</small></div></section><main class="page"><div class="split-grid"><section class="panel"><div class="panel-head">How each threshold is built</div><table><tbody><tr><td>Committed spend</td><td class="amount">'+cash(data.totals.committedMinor)+'</td></tr><tr><td>+ irregular</td><td class="amount">'+cash(data.totals.irregularMinor)+'</td></tr><tr class="group-row"><td>Minimum net</td><td class="amount">'+cash(r.minimumNetIncome.amountMinor)+'</td></tr><tr class="group-row"><td>Minimum gross</td><td class="amount">'+cash(r.minimumGrossIncome.amountMinor)+' '+traceButton(r.minimumGrossIncome)+'</td></tr><tr><td>+ lifestyle</td><td class="amount">'+cash(data.totals.lifestyleMinor)+'</td></tr><tr class="group-row"><td>Sustaining gross</td><td class="amount">'+cash(r.sustainingGrossIncome.amountMinor)+' '+traceButton(r.sustainingGrossIncome)+'</td></tr><tr><td>+ after-tax savings requirement</td><td class="amount">'+cash(data.capital.savingsRequirementMinor)+'</td></tr><tr class="group-row"><td>Comfortable gross</td><td class="amount">'+cash(r.comfortableGrossIncome.amountMinor)+' '+traceButton(r.comfortableGrossIncome)+'</td></tr></tbody></table></section><aside class="side-stack"><div class="card"><h3>Gross → net assumptions</h3><p>Effective tax rate <strong class="amount">'+(data.assumptions.effectiveTaxRateBps/100).toFixed(1)+'%</strong></p><p>Blended annual net income <strong class="amount">'+cash(data.income.annualNetMinor)+'</strong></p><p class="mono">'+esc(data.income.source)+'</p><p>Pre-tax retirement <strong class="amount">'+cash(data.income.pretaxRetirementMinor)+'</strong></p></div><div class="card dark"><h2>'+(data.income.annualNetMinor>=data.totals.householdMinor?'Projected net income sustains the household requirement.':'The household requirement exceeds projected net income.')+'</h2></div></aside></div></main>'); bindTraces(data);
}

async function planCash(){
  const data=await request('/api/plan'), c=data.cash;
  app.innerHTML=planShell(data,'<section class="plan-hero"><div><span class="eyebrow">LIQUID REQUIREMENT</span><h1>'+cash(c.liquidRequirementMinor)+' should be in cash. You hold '+cash(c.cashHeldMinor)+' against it.</h1></div><div><span>OPERATING CASH</span><strong>'+plainCash(c.operatingHeldMinor)+' / '+plainCash(c.operatingTargetMinor)+'</strong>'+meter(c.operatingHeldMinor,c.operatingTargetMinor)+'</div><div><span>EMERGENCY RESERVE</span><strong>'+plainCash(c.emergencyHeldMinor)+' / '+plainCash(c.emergencyTargetMinor)+'</strong>'+meter(c.emergencyHeldMinor,c.emergencyTargetMinor)+'</div><div><span>KNOWN OBLIGATIONS</span><strong>'+plainCash(c.obligationHeldMinor)+' / '+plainCash(c.obligationTargetMinor)+'</strong>'+meter(c.obligationHeldMinor,c.obligationTargetMinor)+'</div></section><main class="page"><div class="split-grid"><section class="side-stack"><div class="card"><h3>Emergency reserve target</h3><p>Blended committed annual spend <strong class="amount">'+cash(data.totals.committedMinor)+'</strong></p><p>Monthly × '+data.assumptions.emergencyCoverageMonths+' months <strong class="amount">'+cash(c.emergencyTargetMinor)+'</strong></p>'+traceButton(data.results.emergencyReserveTarget)+'</div><div class="card"><h3>Operating cash target</h3><p>Greater of the observed 31-day peak or planned monthly ordinary spending plus a '+(data.assumptions.operatingCashBufferBps/100).toFixed(1)+'% buffer.</p><p>Monthly plan <strong class="amount">'+cash(c.plannedMonthlyOrdinaryMinor)+'</strong> · buffered floor <strong class="amount">'+cash(c.budgetOperatingFloorMinor)+'</strong></p><strong class="amount">'+cash(c.operatingTargetMinor)+'</strong> '+traceButton(data.results.operatingCashTarget)+'</div></section><aside class="panel"><div class="panel-head"><span>Known near-term obligations</span><button class="button primary" id="add-obligation">Add</button></div><table><thead><tr><th>Obligation</th><th>Due</th><th class="amount">Amount</th><th></th></tr></thead><tbody>'+data.obligations.map(o=>'<tr><td>'+esc(o.name)+'</td><td>'+date(o.dueDate)+'</td><td class="amount">'+cash(o.amountMinor)+'</td><td><button class="button link delete-obligation" data-id="'+o.id+'">delete</button></td></tr>').join('')+'</tbody></table></aside></div></main>'); bindTraces(data);
  document.querySelector('#add-obligation').onclick=openObligation;
  document.querySelectorAll('.delete-obligation').forEach(b=>b.onclick=async()=>{await request('/api/plan/obligations/'+b.dataset.id,{method:'DELETE'});toast('Obligation removed');planCash()});
}
function openObligation(){modal('Known obligation','<form id="obligation-form" class="form-grid"><div class="field full"><label>NAME</label><input name="name" required></div><div class="field"><label>DUE DATE</label><input name="dueDate" type="date" required></div><div class="field"><label>AMOUNT</label><input name="amount" type="number" min="0" step=".01" required></div><div class="field full"><label>FUNDED FROM ACCOUNT</label><select name="accountId">'+accountOptions()+'</select></div><div class="field full"><label><input type="checkbox" name="funded" style="width:auto"> Mark funded</label></div></form>',async()=>{const f=new FormData(document.querySelector('#obligation-form'));await request('/api/plan/obligations',{method:'POST',body:JSON.stringify({name:f.get('name'),dueDate:f.get('dueDate'),amountMinor:Math.round(Number(f.get('amount'))*100),accountId:f.get('accountId'),funded:f.has('funded')})});closeOverlay();toast('Obligation added');planCash()},'Add obligation')}

async function planSinking(){
  const data=await request('/api/plan');
  app.innerHTML=planShell(data,'<section class="plan-hero"><div class="wide"><span class="eyebrow">SINKING FUNDS</span><h1>'+data.sinkingFunds.length+' target balances totaling '+cash(data.capital.sinkingTargetMinor)+', held '+cash(data.capital.sinkingHeldMinor)+'.</h1></div><div><span>SHORTFALL</span><strong>'+cash(Math.max(0,data.capital.sinkingTargetMinor-data.capital.sinkingHeldMinor))+'</strong></div><div><span>HELD AS CASH</span><strong>'+cash(data.sinkingFunds.filter(f=>f.heldAs==='cash').reduce((s,f)=>s+f.currentBalanceMinor,0))+'</strong></div><div><span>HELD AS INVESTED</span><strong>'+cash(data.sinkingFunds.filter(f=>f.heldAs==='invested').reduce((s,f)=>s+f.currentBalanceMinor,0))+'</strong></div></section><main class="page"><section class="panel"><table><thead><tr><th>Fund</th><th class="amount">Held / target</th><th class="amount">Short</th><th>Horizon</th><th>Held as</th><th>Target basis</th></tr></thead><tbody>'+data.sinkingFunds.map(f=>'<tr><td><strong>'+esc(f.name)+'</strong>'+meter(f.currentBalanceMinor,f.targetBalanceMinor)+'</td><td class="amount">'+cash(f.currentBalanceMinor)+' / '+cash(f.targetBalanceMinor)+'</td><td class="amount amber">'+(f.shortfallMinor?cash(f.shortfallMinor):'—')+'</td><td>'+date(f.nextDueDate)+'</td><td>'+f.heldAs+'</td><td class="mono">'+(f.annualExpectedMinor?cash(f.annualExpectedMinor)+'/yr':'manual target')+'</td></tr>').join('')+'</tbody></table><div class="panel-head"><span>Targets are edited from Budget / Irregular</span><a class="button" href="#irregular">Edit targets</a></div></section></main>');
}

async function planCapital(){
  const data=await request('/api/plan'), c=data.capital;
  app.innerHTML=planShell(data,'<section class="plan-hero"><div class="wide"><span class="eyebrow">CAPACITY AND CAPITAL</span><h1>You can save '+cash(c.savingsCapacityMinor)+' a year, and '+cash(c.growthCapitalMinor)+' is free to grow.</h1></div><div><span>SAVINGS CAPACITY</span><strong>'+cash(c.savingsCapacityMinor)+'</strong></div><div><span>REQUIRED THIS YEAR</span><strong>'+cash(c.savingsRequirementMinor)+'</strong></div><div><span>TOTAL HOLDINGS</span><strong>'+cash(c.totalHoldingsMinor)+'</strong></div></section><main class="page"><div class="split-grid"><section class="card"><h3>Savings capacity</h3><p>Blended annual net income <strong class="amount">'+cash(data.income.annualNetMinor)+'</strong></p><p class="mono">'+esc(data.income.source)+'</p><p>− household requirement <strong class="amount">'+cash(data.totals.householdMinor)+'</strong></p><hr><p><strong>= capacity</strong><strong class="amount" style="float:right">'+cash(c.savingsCapacityMinor)+'</strong></p>'+traceButton(data.results.savingsCapacity)+'</section><aside class="card"><h3>Calculated savings requirement</h3><p>Funds operating, emergency, and known-obligation gaps plus the next year of deadline-paced sinking shortfalls.</p><strong class="amount">'+cash(c.savingsRequirementMinor)+'</strong> '+traceButton(data.results.annualSavingsRequirement)+'</aside></div></main>'); bindTraces(data);
}

async function planAccounts(){
  const data=await request('/api/plan');
  app.innerHTML=planShell(data,'<section class="plan-hero"><div class="wide"><span class="eyebrow">BALANCE PURPOSES</span><h1>Every account balance needs an explicit job.</h1><p>Manual balances remain dated and traceable.</p></div><div><span>TOTAL HOLDINGS</span><strong>'+cash(data.capital.totalHoldingsMinor)+'</strong></div><div><span>ACCOUNTS</span><strong>'+data.accounts.length+'</strong></div><div><span>UNASSIGNED</span><strong>'+data.accounts.filter(a=>a.role.toLowerCase()==='unassigned').length+'</strong></div></section><main class="page"><section class="panel"><table><thead><tr><th>Account</th><th>Assigned purpose</th><th class="amount">Balance</th><th>As of</th><th></th></tr></thead><tbody>'+data.accounts.map(a=>'<tr><td><strong>'+esc(a.name)+'</strong><div class="raw">'+esc(a.institution||'')+(a.lastFour?' ···'+esc(a.lastFour):'')+'</div></td><td>'+esc(a.role)+'</td><td class="amount">'+cash(a.balanceMinor)+'</td><td>'+date(a.balanceAsOf)+'</td><td><button class="button edit-plan-account" data-id="'+a.id+'">Update</button></td></tr>').join('')+'</tbody></table></section></main>');
  document.querySelectorAll('.edit-plan-account').forEach(b=>b.onclick=()=>openPlanAccount(data.accounts.find(a=>a.id===b.dataset.id)));
}
function openPlanAccount(a){modal('Update balance and purpose','<form id="plan-account-form" class="form-grid"><div class="field full"><label>ACCOUNT</label><input disabled value="'+esc(a.name)+'"></div><div class="field full"><label>ASSIGNED PURPOSE</label><select name="role">'+['Operating cash','Emergency reserve','Known near-term obligations','Sinking funds · cash','Growth capital','Spending · paid in full','Unassigned'].map(v=>'<option '+(a.role===v?'selected':'')+'>'+v+'</option>').join('')+'</select></div><div class="field"><label>BALANCE</label><input name="balance" type="number" step=".01" value="'+(Number(a.balanceMinor||0)/100).toFixed(2)+'"></div><div class="field"><label>AS OF</label><input name="balanceAsOf" type="date" value="'+esc(a.balanceAsOf||'')+'"></div></form>',async()=>{const f=new FormData(document.querySelector('#plan-account-form'));await request('/api/accounts/'+a.id,{method:'PATCH',body:JSON.stringify({role:f.get('role'),balanceMinor:Math.round(Number(f.get('balance'))*100),balanceAsOf:f.get('balanceAsOf')})});closeOverlay();toast('Balance purpose updated');await shared();planAccounts()},'Save balance')}

async function planAssumptions(){
  const data=await request('/api/plan'), labels={asOfDate:'As-of date',emergencyCoverageMonths:'Emergency coverage',effectiveTaxRateBps:'Effective tax rate',essentialAverageMonths:'Essential average window',generalAverageMonths:'General average window',irregularHistoryMonths:'Irregular history window',obligationHorizonMonths:'Obligation horizon',investableHorizonYears:'Investable horizon',pretaxRetirementMinor:'Pre-tax retirement',operatingCashBufferBps:'Operating cash buffer'};
  const assumptions=await request('/api/plan/assumptions');
  app.innerHTML=planShell(data,'<section class="plan-hero"><div class="wide"><span class="eyebrow">PLANNING ASSUMPTIONS</span><h1>'+assumptions.length+' explicit inputs separate observed data from calculated answers.</h1></div><div><span>DATA INPUTS</span><strong>'+data.results.householdRequirement.inputReferences.length+'</strong><small>category sources</small></div><div><span>FORMULA</span><strong>v1</strong></div><div><span>ANCHOR</span><strong>'+date(data.asOfDate)+'</strong></div></section><main class="page"><section class="panel"><table><thead><tr><th>Assumption</th><th>In force</th><th>Unit</th><th>Why it exists</th><th></th></tr></thead><tbody>'+assumptions.map(a=>'<tr><td><strong>'+esc(labels[a.key]||a.key)+'</strong><div class="raw">'+esc(a.key)+'</div></td><td class="amount">'+esc(a.value)+'</td><td class="mono">'+esc(a.unit)+'</td><td>'+esc(a.rationale)+'</td><td><button class="button edit-assumption" data-key="'+a.key+'">Edit</button></td></tr>').join('')+'</tbody></table></section><div class="card dark" style="margin-top:22px"><span class="eyebrow">DISCIPLINE</span><h2>If a number cannot name its source, it does not belong in the plan.</h2><p>Results are read-only; only source data and assumptions can be changed.</p></div></main>');
  document.querySelectorAll('.edit-assumption').forEach(b=>{const a=assumptions.find(x=>x.key===b.dataset.key);b.onclick=()=>openAssumption(a,labels[a.key]||a.key)});
}
function openAssumption(a,label){const isDate=a.key==='asOfDate', isMoney=a.unit==='minor-currency', shown=isMoney?Number(a.value)/100:a.value;modal('Edit '+label,'<form id="assumption-form"><div class="field"><label>'+esc(a.unit.toUpperCase())+'</label><input name="value" type="'+(isDate?'date':'number')+'" '+(!isDate?'min="0" step="any"':'')+' value="'+esc(shown)+'" required></div><p class="muted">'+esc(a.rationale)+'</p></form>',async()=>{const f=new FormData(document.querySelector('#assumption-form')),raw=f.get('value'),value=isDate?raw:(isMoney?Math.round(Number(raw)*100):Number(raw));await request('/api/plan/assumptions',{method:'PATCH',body:JSON.stringify({[a.key]:value})});closeOverlay();toast('Assumption updated; plan recalculated');planAssumptions()},'Save assumption')}
function modal(title,body,onSave,label="Save"){document.querySelectorAll(".modal-backdrop").forEach((backdrop)=>backdrop.remove());const node=document.createElement("div");node.className="modal-backdrop";node.innerHTML='<section class="modal"><div class="modal-head"><h2>'+esc(title)+'</h2><button type="button" data-close>×</button></div><div class="modal-body">'+body+'</div><div class="modal-actions"><button type="button" class="button" data-close>Cancel</button><button type="button" class="button primary" id="save-modal">'+esc(label)+'</button></div></section>';document.body.append(node);node.querySelectorAll("[data-close]").forEach(b=>b.onclick=()=>node.remove());const save=node.querySelector("#save-modal"),form=node.querySelector("form");const submit=async()=>{if(save.disabled)return;if(form&&!form.reportValidity())return;save.disabled=true;try{await onSave(node)}catch(e){save.disabled=false;toast(e.message)}};save.onclick=submit;if(form)form.onsubmit=(event)=>{event.preventDefault();submit()};return node}

addEventListener("hashchange",render);
render();
